var session = new InferenceSession("sentinel.onnx");
var inputTensor = new DenseTensor<float>(data, new[] { 1, 60, 34 });
var inputs = new List<NamedOnnxValue> {
    NamedOnnxValue.CreateFromTensor("sensor_window", inputTensor)
};
using var results = session.Run(inputs);
var regimeLogits = results.First(r => r.Name == "regime_logits").AsTensor<float>();
var anomalyScore = results.First(r => r.Name == "anomaly_score").AsTensor<float>();
